359		}
360	
361		chartBefore, err := s.Chart(doc, p.ID)
362		if err != nil {
363			t.Fatal(err)
364		}
365		histBefore := findHistory(chartBefore, r.ID)
366		auditBefore, err := s.AuditEvents(doc, p.ID)
367		if err != nil {
368			t.Fatal(err)
369		}
370		readBefore, err := s.Read(rcv, p.ID, e.ID, Diagnosis)
371		if err != nil {
372			t.Fatal(err)
373		}
374	
375		// 所有坏序列（出现在开头/中间/结尾、夹在中文之间、单个坏字节等）
376		// 都用当前版本号 2 提交：一律 ErrInvalidArgument，历史与审计原样。
377		for _, tc := range invalidContents {
378			if _, err := s.CorrectRecord(doc, r.ID, 2, tc.content, "更正原因合法"); !errors.Is(err, ErrInvalidArgument) {
379				t.Fatalf("%s: CorrectRecord err = %v, want ErrInvalidArgument", tc.label, err)
380			}
381			chart, err := s.Chart(doc, p.ID)
382			if err != nil {
383				t.Fatal(err)
384			}
385			hist := findHistory(chart, r.ID)
386			if hist == nil || hist.CurrentVersion == nil {
387				t.Fatalf("%s: history missing", tc.label)
388			}
389			cur := hist.CurrentVersion
390			if cur.ID != v2.ID || cur.Number != 2 || cur.Content != v2.Content ||
391				cur.PrevID != v1.ID || cur.Reason != v2.Reason {
392				t.Fatalf("%s: current version changed: %+v", tc.label, cur)
393			}
394			if hist.Record.CurrentVersionID != v2.ID || len(hist.Versions) != 2 ||
395				!reflect.DeepEqual(hist.Record.Versions, []ID{v1.ID, v2.ID}) ||
396				!reflect.DeepEqual(hist.Versions[0], v1) || !reflect.DeepEqual(hist.Versions[1], v2) {
397				t.Fatalf("%s: version history changed: %+v", tc.label, hist)
398			}
399			audit, err := s.AuditEvents(doc, p.ID)
400			if err != nil {
401				t.Fatal(err)
402			}
403			if !reflect.DeepEqual(audit, auditBefore) {
404				t.Fatalf("%s: correction audit added on rejected correction", tc.label)
405			}
406			res, err := s.Read(rcv, p.ID, e.ID, Diagnosis)
407			if err != nil {
408				t.Fatal(err)
409			}
410			if !reflect.DeepEqual(res, readBefore) {
411				t.Fatalf("%s: receiver read changed:\nbefore: %+v\nafter:  %+v", tc.label, readBefore, res)
412			}
413		}
414	
415		// 拒绝后重开：当前版本、旧版本与版本关系仍是原来的结果。
416		s = reopenStore(t, s, dir, clk)
417		if got := findHistory(mustChart(t, s, p.ID), r.ID); !reflect.DeepEqual(got, histBefore) {
418			t.Fatalf("history changed after rejected corrections + reopen:\nbefore: %+v\nafter:  %+v", histBefore, got)
419		}
420	
421		// 空串与全空白正文继续按既有规则拒绝，历史不变。
422		for _, blank := range []string{"", "  \n\t ", "　"} {
423			if _, err := s.CorrectRecord(doc, r.ID, 2, blank, "原因"); !errors.Is(err, ErrInvalidArgument) {
424				t.Fatalf("blank correction %q err = %v, want ErrInvalidArgument", blank, err)
425			}
426		}
427		if got := findHistory(mustChart(t, s, p.ID), r.ID); !reflect.DeepEqual(got, histBefore) {
428			t.Fatalf("blank correction changed history: %+v", got)
429		}
430	
431		// 失败的更正没有推进版本号：仍用此前的当前版本号 2 提交合法正文，
432		// 成功生成紧接 v2 的第 3 版，只新增这一次真正完成的更正审计。
433		clk.t = clk.t.Add(time.Hour)
434		valid := "三次复诊：血压 118/76 🩸，e\u0301 组合\n\"引号\" C:\\路径 \ufffd 随访  "
435		v3, err := s.CorrectRecord(doc, r.ID, 2, valid, "坏字节拒绝后的合法更正")
436		if err != nil {
437			t.Fatalf("valid correction after rejections: %v", err)
438		}
439		if v3.Number != 3 || v3.PrevID != v2.ID || v3.Content != valid ||
440			v3.Reason != "坏字节拒绝后的合法更正" || !v3.CreatedAt.Equal(clk.t) {
441			t.Fatalf("unexpected v3: %+v", v3)
442		}
443	
444		chart, err := s.Chart(doc, p.ID)
445		if err != nil {
446			t.Fatal(err)
447		}
448		hist := findHistory(chart, r.ID)
449		if hist == nil || hist.CurrentVersion == nil || hist.CurrentVersion.ID != v3.ID ||
450			len(hist.Versions) != 3 ||
451			!reflect.DeepEqual(hist.Versions[0], v1) || !reflect.DeepEqual(hist.Versions[1], v2) ||
452			!reflect.DeepEqual(hist.Versions[2], v3) {
453			t.Fatalf("history after valid correction: %+v", hist)
454		}
455		audit, err := s.AuditEvents(doc, p.ID)
456		if err != nil {
457			t.Fatal(err)
458		}
459		if len(audit) != len(auditBefore)+1 || !reflect.DeepEqual(audit[:len(auditBefore)], auditBefore) {
460			t.Fatalf("audit after valid correction:\nbefore: %+v\nafter:  %+v", auditBefore, audit)
461		}
462		last := audit[len(audit)-1]
463		if last.Action != ActionCorrected || last.ObjectID != r.ID || last.ActorID != doc.ID {
464			t.Fatalf("unexpected new audit event: %+v", last)
465		}
466	
467		// 合法正文的既有版本号校验继续成立：过期版本号返回 ErrConflict，
468		// 状态与审计不变。
469		if _, err := s.CorrectRecord(doc, r.ID, 2, "用过期版本号更正", "过期"); !errors.Is(err, ErrConflict) {
470			t.Fatalf("stale version correction err = %v, want ErrConflict", err)
471		}
472		chart, err = s.Chart(doc, p.ID)
473		if err != nil {
474			t.Fatal(err)
475		}
476		if hist = findHistory(chart, r.ID); hist.CurrentVersion.ID != v3.ID || len(hist.Versions) != 3 {
477			t.Fatalf("rejected stale correction changed history: %+v", hist)
478		}
479		audit2, err := s.AuditEvents(doc, p.ID)
480		if err != nil {
481			t.Fatal(err)
482		}
483		if !reflect.DeepEqual(audit2, audit) {
484			t.Fatal("rejected stale correction added an audit event")
485		}
486	
487		// 接收方读到新的当前版本，合法正文逐字一致。
488		res, err := s.Read(rcv, p.ID, e.ID, Diagnosis)
489		if err != nil {
490			t.Fatal(err)
491		}
492		if len(res.Records) != 1 || res.Records[0].VersionID != v3.ID ||
493			res.Records[0].Version != 3 || res.Records[0].Content != valid {
494			t.Fatalf("receiver read after valid correction: %+v", res.Records)
495		}
496	
497		// 关闭后从同一位置重新打开：三个版本（含各自原文、PrevID 与原因）
498		// 与审计完整保持，当前版本仍是逐字原文的第 3 版。
499		s = reopenStore(t, s, dir, clk)
500		t.Cleanup(func() { _ = s.Close() })
501		chart, err = s.Chart(doc, p.ID)
502		if err != nil {
503			t.Fatal(err)
504		}
505		hist = findHistory(chart, r.ID)
506		if hist == nil || len(hist.Versions) != 3 {
507			t.Fatalf("history after reopen: %+v", hist)
508		}
509		if !reflect.DeepEqual(hist.Versions[0], v1) || !reflect.DeepEqual(hist.Versions[1], v2) {
510			t.Fatalf("older versions changed after reopen: %+v", hist.Versions)
511		}
512		if got := hist.Versions[2]; got.Content != valid || got.PrevID != v2.ID ||
513			got.Reason != "坏字节拒绝后的合法更正" {
514			t.Fatalf("v3 after reopen mismatch: %+v", got)
515		}
516		audit3, err := s.AuditEvents(doc, p.ID)
517		if err != nil {
518			t.Fatal(err)
519		}
520		if !reflect.DeepEqual(audit3, audit) {
521			t.Fatal("audit events changed after reopen")
522		}
523	}
524	
525	// TestInvalidUTF8RejectedWhenPatientDeactivated 保证 UTF-8 校验先行：
526	// 患者停用后夹带坏字节的写操作仍返回 ErrInvalidArgument（而非以停用错误
527	// 落盘或静默保存），且状态不变。
528	func TestInvalidUTF8RejectedWhenPatientDeactivated(t *testing.T) {
529		s, clk := newTestStore(t)
530		pid, eid := setupPatientEncounter(t, s)
531		r, err := s.CreateDraft(doc, pid, eid, Order, "医嘱草稿原文")
532		if err != nil {
533			t.Fatal(err)
534		}
535		v1, err := s.ActivateRecord(doc, r.ID)
536		if err != nil {
537			t.Fatal(err)
538		}
539		clk.t = clk.t.Add(time.Hour)
540		if err := s.DeactivatePatient(doc, pid); err != nil {
541			t.Fatal(err)
542		}
543	
544		if _, err := s.CreateDraft(doc, pid, eid, Order, "停用后\xff坏草稿"); !errors.Is(err, ErrInvalidArgument) {
545			t.Fatalf("deactivated create with bad utf8 err = %v, want ErrInvalidArgument", err)
546		}
547		if _, err := s.UpdateDraft(doc, r.ID, "停用后\xff坏草稿"); !errors.Is(err, ErrInvalidArgument) {
548			t.Fatalf("update active record with bad utf8 err = %v, want ErrInvalidArgument", err)
549		}
550		if _, err := s.CorrectRecord(doc, r.ID, 1, "停用后\xff坏更正", "原因"); !errors.Is(err, ErrInvalidArgument) {
551			t.Fatalf("deactivated correct with bad utf8 err = %v, want ErrInvalidArgument", err)
552		}
553		chart, err := s.Chart(doc, pid)
554		if err != nil {
555			t.Fatal(err)
556		}
557		hist := findHistory(chart, r.ID)
558		if hist == nil || hist.CurrentVersion == nil || hist.CurrentVersion.ID != v1.ID ||
559			len(hist.Versions) != 1 {
560			t.Fatalf("bad-utf8 writes after deactivation changed history: %+v", hist)
561		}
562	}
563	
564	// reopenStore 关闭现有句柄并从同一目录重新打开（沿用注入时钟）。
565	func reopenStore(t *testing.T, s *Store, dir string, clk *fakeClock) *Store {
566		t.Helper()
567		if err := s.Close(); err != nil {
568			t.Fatalf("close: %v", err)
569		}
570		s2, err := Open(dir, WithClock(func() time.Time { return clk.t }))
571		if err != nil {
572			t.Fatalf("reopen: %v", err)
573		}
574		return s2
575	}
576	
577	func mustChart(t *testing.T, s *Store, patientID ID) PatientChart {
578		t.Helper()
579		chart, err := s.Chart(doc, patientID)
580		if err != nil {
581			t.Fatalf("chart: %v", err)
582		}
583		return chart
584	}
